import statistics
from collections import defaultdict
import json
from typing import Dict, Any


def task_func(data_list: list, json_file_name: str) ->Dict[str, float]:

    def calculate_means():
        position_data = defaultdict(list)
        for item in data_list:
            for i, value in enumerate(item[1:], 1):
                position_data[f'Position {i}'].append(value)
        results = {}
        for pos, values in position_data.items():
            if len(values) == 0:
                continue
            try:
                mean = statistics.mean(values)
                results[pos] = float(mean)
            except statistics.StatisticsError:
                pass
        return results

    def save_to_json(results: Dict[str, Any], file_name: str):
        with open(file_name, 'w') as f:
            json.dump(results, f)
    results = calculate_means()
    save_to_json(results, json_file_name)
    return results

