import random
import logging
logger = logging.getLogger(__name__)


def task_func(department_dict):
    if not isinstance(department_dict, dict):
        raise TypeError('Input must be a dictionary')
    result = {}
    for dept_code, employee_count in department_dict.items():
        if not isinstance(dept_code, str):
            logger.warning('Department code is not a string: %r', dept_code)
            continue
        if not dept_code.startswith('EMP$$'):
            continue
        if not isinstance(employee_count, int):
            logger.warning('Employee count is not an integer for %s: %r',
                dept_code, employee_count)
            continue
        if employee_count < 0:
            raise ValueError(f'Negative employee count for {dept_code}')
        salaries = [random.randint(1, 100) for _ in range(employee_count)]
        result[dept_code] = salaries
    return result

