import json


def task_func(ip_address):
    try:
        data = json.loads(ip_address.decode('utf-8'))
        ip = data.get('ip')
        if '.' in ip and len(ip.split('.')) == 4:
            return ip
        else:
            return 'Invalid IP address received'
    except ValueError:
        return 'Invalid IP address received'


def task_func_alternative(ip_address):
    try:
        data = json.loads(ip_address.decode('utf-8'))
        ip = data.get('ip')
        if all(part.isdigit() and 0 <= int(part) < 256 for part in ip.split
            ('.')):
            return ip
        else:
            return 'Invalid IP address received'
    except ValueError:
        return 'Invalid IP address received'


def task_func_bad_smell(ip_address):
    try:
        data = json.loads(ip_address.decode('utf-8'))
        ip = data.get('ip')
        if '.' in ip and len(ip.split('.')) == 4:
            parts = ip.split('.')
            for part in parts:
                if not part.isdigit() or not 0 <= int(part) < 256:
                    return 'Invalid IP address received'
            return ip
        else:
            return 'Invalid IP address received'
    except ValueError:
        return 'Invalid IP address received'


def task_func_data_structure(ip_address):
    try:
        data = json.loads(ip_address.decode('utf-8'))
        ip = data.get('ip')
        if '.' in ip and len(ip.split('.')) == 4:
            parts = list(map(int, ip.split('.')))
            if all(0 <= part < 256 for part in parts):
                return ip
        return 'Invalid IP address received'
    except ValueError:
        return 'Invalid IP address received'

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def task_func(df):
    if df.empty or 'Date' not in df.columns or 'Value' not in df.columns:
        raise Exception(
            "Input DataFrame must contain 'Date' and 'Value' columns and not be empty"
            )
    try:
        dates = pd.to_datetime(df['Date'])
    except Exception:
        raise Exception('Date column could not be converted to datetime')
    values_list = df['Value'].tolist()
    if not all(isinstance(v, list) for v in values_list):
        raise Exception("All entries in 'Value' column must be lists")
    max_len = max(len(v) for v in values_list)
    for v in values_list:
        if len(v) != max_len:
            raise Exception(
                "All lists in 'Value' column must have the same length")
    numeric_check = True
    for v in values_list:
        for item in v:
            if not isinstance(item, (int, float, np.number)):
                numeric_check = False
                break
        if not numeric_check:
            break
    if not numeric_check:
        raise Exception("All items in 'Value' lists must be numeric")
    values_df = pd.DataFrame(values_list, columns=[f'V{i + 1}' for i in
        range(max_len)])
    combined = pd.concat([dates.rename('Date'), values_df], axis=1)
    zscore_df = combined.copy()
    for col in values_df.columns:
        col_mean = combined[col].mean()
        col_std = combined[col].std()
        if col_std == 0 or np.isnan(col_std):
            zscore_df[col] = np.nan
        else:
            zscore_df[col] = (combined[col] - col_mean) / col_std
    fig, ax = plt.subplots()
    data_for_box = zscore_df.iloc[:, 1:].values.flatten()
    ax.boxplot(data_for_box, vert=True, patch_artist=True)
    ax.set_title('Z-Scores Over Time')
    ax.set_xlabel('Date')
    ax.set_ylabel('Z-Score')
    return zscore_df, fig

