import json


def task_func(data_list, json_file_name):
    positions = {}
    for item in data_list:
        pos_index = 0
        while pos_index < len(item) - 1:
            if pos_index + 1 not in positions:
                positions[pos_index + 1] = []
            positions[pos_index + 1].append(item[pos_index + 1])
            pos_index += 1
    mean_values = {}
    for pos, values in positions.items():
        mean = sum(values) / len(values)
        mean_values[f'Position {pos}'] = mean
    with open(json_file_name, 'w') as f:
        json.dump(mean_values, f)
    return mean_values

import os
import logging


def task_func(directory):
    logging.basicConfig(filename='jquery_removal.log', level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s')
    if not os.path.exists(directory):
        raise FileNotFoundError(f"Directory '{directory}' does not exist.")
    file_list = os.listdir(directory)
    removed_files = []
    for file_name in file_list:
        if 'jquery' in file_name.lower() and file_name.endswith('.js'):
            try:
                file_path = os.path.join(directory, file_name)
                os.remove(file_path)
                removed_files.append(file_name)
                logging.info(f'Successfully removed: {file_name}')
            except OSError as e:
                logging.error(f'Failed to remove {file_name}: {str(e)}')
    return len(removed_files), removed_files

import matplotlib.pyplot as plt


def task_func(column, data):
    if not data:
        raise Exception('Data cannot be empty')
    if column not in ['Product', 'Quantity Sold', 'Total Sales']:
        raise KeyError(f'Invalid column: {column}')
    for row in data:
        if len(row) < 3:
            raise Exception('Row does not contain enough elements')
        quantity, total = row[1], row[2]
        if quantity < 0 or total < 0:
            raise Exception('Negative values are not allowed')
    if column == 'Quantity Sold':
        values = [row[1] for row in data]
    elif column == 'Total Sales':
        values = [row[2] for row in data]
    else:
        values = [row[0] for row in data]
    stats = {'sum': sum(values), 'mean': sum(values) / len(values), 'min':
        min(values), 'max': max(values)}
    products = [row[0] for row in data]
    fig, ax = plt.subplots()
    ax.bar(products, values)
    ax.set_title(f'Bar Chart of {column}')
    return stats, ax

