import numpy as np


def task_func(myList):
    if not isinstance(myList, list):
        raise TypeError('Input must be a list')
    try:
        arr = np.array(myList)
        if not np.isfinite(arr).all():
            raise ValueError(
                'All values in the list must be numeric and finite')
        if len(arr) == 0:
            return np.array([])
        elif len(arr) == 1:
            return np.array([0.0])
        min_val = arr.min()
        max_val = arr.max()
        if min_val == max_val:
            normalized_arr = np.zeros_like(arr)
        else:
            normalized_arr = (arr - min_val) / (max_val - min_val)
        return normalized_arr
    except Exception as e:
        raise RuntimeError(f'An error occurred during normalization: {e}')

