import json
from http import HTTPStatus


class PostRequestHandler:

    def __init__(self):
        self.error_response = {'status': 'error', 'message': ''}
        self.success_response = {'status': 'success', 'message':
            'Data received successfully.'}

    def do_POST(self, request):
        if not self._is_valid_content_type(request.headers.get('Content-Type')
            ):
            return self._send_error_response(HTTPStatus.BAD_REQUEST)
        try:
            message = json.loads(request.rfile.read(int(request.headers.get
                ('Content-Length'))))
        except ValueError:
            return self._send_error_response(HTTPStatus.BAD_REQUEST)
        if 'data' not in message:
            return self._send_error_response(HTTPStatus.BAD_REQUEST)
        return self._send_success_response()

    def _is_valid_content_type(self, content_type):
        return content_type == 'application/json'

    def _send_error_response(self, status_code):
        self.send_response(status_code)
        self.end_headers()
        self.wfile.write(json.dumps(self.error_response).encode())
        return

    def _send_success_response(self):
        self.send_response(HTTPStatus.OK)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(self.success_response).encode())
        return


def task_func():
    return PostRequestHandler

import requests


def task_func(data_url: str):
    if not data_url:
        return 'Invalid url input'
    try:
        response = requests.get(data_url)
    except Exception:
        return 'Invalid url input'
    if not isinstance(response, requests.Response):
        return 'Invalid url input'
    try:
        data = response.json()
    except Exception:
        return 'Invalid url input'
    names = data.get('names')
    if not isinstance(names, list):
        return 'Invalid url input'
    return [name for name in names if '[' not in name and ']' not in name]

import numpy as np


def task_func(myList):
    stats = {'min': min(myList), 'max': max(myList)}
    stats_dup = {'min': min(myList), 'max': max(myList)}
    range_val = stats['max'] - stats['min']
    if range_val == 0:
        return np.array([0] * len(myList))
    normalized = [((x - stats['min']) / range_val) for x in myList]
    normalized_dup = [((x - stats_dup['min']) / (stats_dup['max'] -
        stats_dup['min'])) for x in myList]
    return np.array(normalized)

