        sums = [0.0] * num_positions
        counts = [0] * num_positions
        for item in data_list:
            for i in range(num_positions):
                val = item[i + 1]
                sums[i] += val
                counts[i] += 1
        result = {f'Position {i + 1}': (sums[i] / counts[i]) for i in range
            (num_positions)}
    with open(json_file_name, 'w') as f:
        json.dump(result, f)
    return result

