import pandas as pd
import re


def task_func(df: pd.DataFrame, column_name: str, pattern: str) ->pd.DataFrame:
    """
    Reverse the order of words in a specific DataFrame column where the words match a regular expression pattern.
    Non-matching words retain their original order. Returns an unaltered DataFrame if the pattern is empty.
    """

    def _word_reverser(text: str, regex_pattern: str) ->str:
        if not regex_pattern.strip():
            return text
        words = text.split()
        match_indices = []
        match_words = []
        for i, word in enumerate(words):
            if re.fullmatch(regex_pattern, word):
                match_indices.append(i)
                match_words.append(word)
        for idx, new_word in zip(match_indices, reversed(match_words)):
            words[idx] = new_word
        return ' '.join(words)
    if not isinstance(df, pd.DataFrame):
        raise TypeError('Input must be a pandas DataFrame')
    if column_name not in df.columns:
        raise KeyError(
            f"Column '{column_name}' does not exist in the DataFrame")
    if not isinstance(pattern, str):
        raise ValueError('Pattern must be a string')
    result_df = df.copy()
    result_df[column_name] = result_df[column_name].apply(lambda x:
        _word_reverser(x, pattern))
    return result_df

