        raise ValueError('Articles list is empty')
    converted_times = []
    for article in articles:
        if 'published_time' not in article or 'category' not in article:
            raise ValueError('Invalid article format')
        try:
            original_datetime = article['published_time']
            target_tz = pytz.timezone(timezone)
            converted_time = original_datetime.astimezone(target_tz).hour
            converted_times.append({'category': article['category'], 'time':
                converted_time})
        except Exception as e:
            raise ValueError(f'Error converting time for article: {e}')
    df = pd.DataFrame(converted_times)
    grouped_df = df.groupby('category')['time'].agg(['count', 'mean', 'min',
        'max'])
    return grouped_df.astype({'count': 'int64', 'min': 'int32', 'max':
        'int32', 'mean': 'float64'})

