import random
import math
import pandas as pd


def task_func(*args):
    DEFAULT_N = 5000
    DEFAULT_MIN = 0.0
    DEFAULT_MAX = 10.0
    if len(args) == 0:
        n_data_points, min_value, max_value = (DEFAULT_N, DEFAULT_MIN,
            DEFAULT_MAX)
    elif len(args) == 3:
        n_data_points, min_value, max_value = args
    else:
        raise ValueError('Expected either 0 or 3 arguments')
    if not isinstance(n_data_points, int) or n_data_points <= 0:
        raise ValueError('Number of data points must be a positive integer')
    if not (isinstance(min_value, (int, float)) and isinstance(max_value, (
        int, float))):
        raise ValueError('min_value and max_value must be numeric')
    if max_value < min_value:
        raise ValueError('max_value must be greater than or equal to min_value'
            )
    raw_values = [round(random.uniform(min_value, max_value), 3) for _ in
        range(n_data_points)]
    mean_val = sum(raw_values) / n_data_points
    variance = sum((x - mean_val) ** 2 for x in raw_values) / n_data_points
    std_dev = math.sqrt(variance)
    if std_dev == 0:
        raise ValueError('Standard deviation is zero; cannot normalize')
    normalized = [((x - mean_val) / std_dev) for x in raw_values]
    return pd.DataFrame(normalized, columns=['Normalized Value'])

