from geopy.distance import geodesic
import folium


def task_func(locations_dict):
    """Generates a Folium map with markers and calculates geodesic distances between locations."""
    if not locations_dict:
        raise ValueError('Input dictionary is empty.')
    first_loc = next(iter(locations_dict.values()))
    folium_map = folium.Map(location=[first_loc['Lat'], first_loc['Lon']],
        zoom_start=4)
    markers = {loc_name: folium.Marker([loc_info['Lat'], loc_info['Lon']],
        popup=loc_name) for loc_name, loc_info in locations_dict.items()}
    for marker in markers.values():
        marker.add_to(folium_map)
    distance_pairs = {}
    location_points = {loc_name: (loc_info['Lat'], loc_info['Lon']) for 
        loc_name, loc_info in locations_dict.items()}
    for i, loc1 in enumerate(locations_dict):
        for j, loc2 in enumerate(locations_dict):
            if i < j:
                lat1, lon1 = location_points[loc1]
                lat2, lon2 = location_points[loc2]
                distance = geodesic((lat1, lon1), (lat2, lon2)).kilometers
                distance_pairs[loc1, loc2] = distance
    return folium_map, distance_pairs

