        if not numeric_values:
            mean_values.append(np.nan)
        else:
            mean_val = np.mean([float(v) for v in numeric_values])
            mean_values.append(mean_val)
    return mean_values

import numpy as np
from typing import List


def task_func(myList: List[float]) ->np.ndarray:
    """
    Normalizes a list of numeric values to the range [0, 1] using min-max scaling.
    """
    try:
        if not all(isinstance(x, (int, float)) for x in myList):
            raise ValueError('Input list must contain only numeric values.')
        normalized_list = np.array(myList)
        min_val = np.min(normalized_list)
        max_val = np.max(normalized_list)
        if min_val == max_val:
            return np.zeros_like(normalized_list)
        normalized_list = (normalized_list - min_val) / (max_val - min_val)
        return normalized_list
    except Exception as e:
        raise ValueError(f'An error occurred during normalization: {e}')

