import re


def task_func(word: str) ->list:
    cleaned_word = re.sub('[^a-z]', '', word.lower())
    if len(cleaned_word) < 2:
        return []
    pair_counts = {}
    for i in range(len(cleaned_word) - 1):
        pair = cleaned_word[i:i + 2]
        if pair in pair_counts:
            pair_counts[pair] += 1
        else:
            pair_counts[pair] = 1
    most_common_pair = max(pair_counts, key=pair_counts.get)
    frequency = pair_counts[most_common_pair]
    return [(most_common_pair, frequency)]

