import os


def task_func(file_name):
    if not os.path.isfile(file_name):
        raise FileNotFoundError('The specified file does not exist.')
    data_list = []
    header_set = set()
    row_count = 0
    try:
        with open(file_name, 'r', newline='') as csvfile:
            csvreader = csv.reader(csvfile)
            for row in csvreader:
                if row_count == 0:
                    headers = row
