import random
from typing import List, Tuple, Any, Optional


def task_func(obj_list: List[Any], attr: str, top_n: int, seed: int) ->Tuple[
    List[int], Optional[int]]:
    if not isinstance(obj_list, list):
        raise TypeError('obj_list must be a list')
    if not isinstance(attr, str):
        raise TypeError('attr must be a string')
    if not isinstance(top_n, int):
        raise TypeError('top_n must be an integer')
    if not isinstance(seed, (int, float)):
        raise TypeError('seed must be a number')
    if not obj_list:
        return [], None
    values = []
    for obj in obj_list:
        if not hasattr(obj, attr):
            raise AttributeError(f"Object {obj} lacks attribute '{attr}'")
        val = getattr(obj, attr)
        if not isinstance(val, int):
            raise TypeError(f"Attribute '{attr}' must be an integer")
        values.append(val)
    top_values = sorted(values, reverse=True)[:top_n]
    random.seed(seed)
    rand_value = random.choice(values)
    return top_values, rand_value

