import pandas as pd
import re


def task_func(file_path: str) ->pd.DataFrame:

    def parse_log_line(line):
        match = re.match(
            '(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}\\.\\d{6}) - (\\w+) - (.+)$'
            , line)
        if match:
            return match.groups()
        else:
            return None

    def process_log_file(file_path):
        logs = []
        with open(file_path, 'r') as f:
            for line in f:
                log_data = parse_log_line(line.strip())
                if log_data is not None:
                    logs.append(log_data)
        return logs

    def create_dataframe(logs):
        if len(logs) == 0:
            return pd.DataFrame(columns=['Timestamp', 'Level', 'Message'])
        else:
            df = pd.DataFrame(logs, columns=['Timestamp', 'Level', 'Message'])
            return df
    logs = process_log_file(file_path)
    df = create_dataframe(logs)
    return df

