        return web.Response(text=json.dumps({'status': 'error', 'message':
            'Invalid HTTP method'}), status=405)
    try:
        data = await request.json()
    except ValueError as e:
        return web.Response(text=json.dumps({'status': 'error', 'message':
            str(e)}), status=400)
    if 'data' not in data:
        return web.Response(text=json.dumps({'status': 'error', 'message':
            'No data received'}), status=400)
