import os


def task_func(log_file_path: str, keywords: list):
    if not os.path.exists(log_file_path):
        raise FileNotFoundError(f'Log file {log_file_path} does not exist.')
    keyword_set = set(keywords)
    formatted_lines = []
    with open(log_file_path, 'r') as log:
        for line in log:
            parts = line.strip().split()
            if any(part in keyword_set for part in parts):
                try:
                    timestamp_index = next(i for i, part in enumerate(parts
                        ) if part.isdigit() and len(part) == 4)
                    message = ' '.join(parts[:timestamp_index] + parts[
                        timestamp_index + 1:])
                    formatted_line = (
                        f'{parts[next(i for i, part in enumerate(parts) if part in keyword_set)]!s:20} : {parts[timestamp_index]:20} : {message:20}'
                        )
                    formatted_lines.append(formatted_line)
                except (StopIteration, ValueError):
                    formatted_lines.append(
                        f'Line format unexpected: {line.strip()}')
    return formatted_lines

import random


def task_func(values, weights, n_samples):
    """
    Samples random numbers based on a given weighted distribution and returns a histogram of the samples.
    """
    total_weight = sum(weights)
    histogram = {}
    for _ in range(n_samples):
        r = random.uniform(0, total_weight)
        cumulative_weight = 0
        for i, weight in enumerate(weights):
            cumulative_weight += weight
            if r <= cumulative_weight:
                histogram[values[i]] = histogram.get(values[i], 0) + 1
                break
    return histogram

