def task_func(array):
    if not isinstance(array, list) or any(not isinstance(row, list) for row in
        array):
        raise TypeError('Input must be a 2D list of lists')
    n_rows = len(array)
    if n_rows == 0:
        raise IndexError('The input list is empty')
    n_cols = len(array[0])
    if any(len(row) != n_cols for row in array):
        raise TypeError('All rows must have the same length')
    df = pd.DataFrame(array, columns=[chr(65 + i) for i in range(n_cols)])
    distance_matrix = np.zeros((n_rows, n_rows))
    for i in range(n_rows):
        for j in range(i + 1, n_rows):
            dist = np.linalg.norm(np.array(array[i]) - np.array(array[j]))
            distance_matrix[i, j] = dist
            distance_matrix[j, i] = dist
    return df, pd.DataFrame(distance_matrix)

