import logging
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)


def task_func(points):
    if not isinstance(points, (list, tuple)):
        raise TypeError('Input must be a list or tuple of points')
    if len(points) < 2:
        return []
    distances = []
    for idx in range(len(points) - 1):
        p1 = points[idx]
        p2 = points[idx + 1]
        if not isinstance(p1, (list, tuple)) or not isinstance(p2, (list,
            tuple)):
            raise TypeError('Each point must be a list or tuple of numbers')
        if len(p1) == 1:
            x1 = y1 = p1[0]
        elif len(p1) == 2:
            x1, y1 = p1
        else:
            raise ValueError('Point must contain one or two numeric values')
        if len(p2) == 1:
            x2 = y2 = p2[0]
        elif len(p2) == 2:
            x2, y2 = p2
        else:
            raise ValueError('Point must contain one or two numeric values')
        try:
            dx = float(x2) - float(x1)
            dy = float(y2) - float(y1)
        except (TypeError, ValueError) as exc:
            raise TypeError('Point coordinates must be numeric') from exc
        dist = math.hypot(dx, dy)
        distances.append(dist)
        logger.debug('Computed distance between point %s and %s: %f', p1,
            p2, dist)
    return distances

