import base64
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives import hashes
from cryptography.exceptions import InvalidSignature


def task_func(num: str, from_base: int, to_base: int, private_key: rsa.
    RSAPrivateKey, alphabet: str) ->str:
    """
    Converts a number between bases, signs it with an RSA private key,
    and encodes the result using a custom base64 alphabet.
    """
    try:
        n = int(num, from_base)
    except ValueError as e:
        raise ValueError(f'Invalid number for base {from_base}') from e
    digits = []
    if n == 0:
        digits.append(0)
    else:
        while n > 0:
            n, m = divmod(n, to_base)
            digits.append(m)
    try:
        encoded_num = ''.join([alphabet[d] for d in reversed(digits)])
    except IndexError as e:
        raise ValueError('Custom alphabet does not contain enough characters'
            ) from e
    data = bytes(encoded_num, 'utf-8')
    try:
        signature = private_key.sign(data, padding.PSS(mgf=padding.MGF1(
            hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH), hashes.
            SHA256())
    except InvalidSignature as e:
        raise RuntimeError('Failed to sign data') from e
    b64_encoded = base64.b64encode(signature)
    return b64_encoded.decode('utf-8')

