import random


def task_func(t, n):

    def gen_combs(seq, k):
        if k == 0:
            return [()]
        if len(seq) < k:
            return []
        res = []
        for i in range(len(seq)):
            for comb in gen_combs(seq[i + 1:], k - 1):
                res.append((seq[i],) + comb)
        res2 = []
        for j in range(len(seq)):
            for comb in gen_combs(seq[j + 1:], k - 1):
                res2.append((seq[j],) + comb)
        res.extend(res2)
        return res
    all_combs = gen_combs(t, n)
    comb_dict = {i: comb for i, comb in enumerate(all_combs)}
    rand_key = random.randint(0, len(comb_dict) - 1)
    return comb_dict[rand_key]

