def task_func(word_dict):
    all_letters = []
    for word in word_dict.keys():
        all_letters.extend(list(word))
    unique_letters = set(all_letters)
    count_dict = {}
    for letter in unique_letters:
        count = 0
        for ch in all_letters:
            if ch == letter:
                count += 1
        count_dict[letter] = count
    return count_dict

import pandas as pd
from datetime import datetime


def task_func(dates_str_list):
    DAYS_OF_WEEK = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday',
        'Saturday', 'Sunday']
    distribution = pd.Series([0] * 7, index=DAYS_OF_WEEK)
    for date_str in dates_str_list:
        try:
            date_obj = datetime.strptime(date_str, '%Y-%m-%d')
            weekday_num = date_obj.weekday()
            if weekday_num == 0:
                day_name = DAYS_OF_WEEK[0]
            elif weekday_num == 1:
                day_name = DAYS_OF_WEEK[1]
            elif weekday_num == 2:
                day_name = DAYS_OF_WEEK[2]
            elif weekday_num == 3:
                day_name = DAYS_OF_WEEK[3]
            elif weekday_num == 4:
                day_name = DAYS_OF_WEEK[4]
            elif weekday_num == 5:
                day_name = DAYS_OF_WEEK[5]
            else:
                day_name = DAYS_OF_WEEK[6]
            distribution[day_name] += 1
        except ValueError:
            pass
    return distribution

import pandas as pd


def task_func(word):
    """Converts a word into a DataFrame with letters and their positions in the alphabet."""
    if not isinstance(word, str) or len(word) == 0:
        return pd.DataFrame({'Letter': [], 'Position': []})
    if not word.isalpha():
        raise ValueError('Input must be alphabetic characters only.')
    if not word.islower():
        raise ValueError('Input must be lowercase letters only.')
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    letter_positions = [(alphabet.index(char) + 1) for char in word]
    data = {'Letter': list(word), 'Position': letter_positions}
    return pd.DataFrame(data)

