import hashlib


def task_func(input_string, *args):
    if not isinstance(input_string, str):
        raise TypeError
    if not isinstance(input_string, str):
        raise TypeError
    verify_hash = args[0] if args else None
    if verify_hash is not None and not isinstance(verify_hash, str):
        raise TypeError
    if verify_hash is not None and not isinstance(verify_hash, str):
        raise TypeError
    h = hashlib.sha256()
    h.update(input_string.encode('utf-8'))
    digest = h.hexdigest()
    if verify_hash is not None:
        if digest == verify_hash:
            return True
        else:
            return False
    else:
        return digest

