import pathlib


def task_func(log_file_path: str, keywords: list):
    path = pathlib.Path(log_file_path)
    if not path.is_file():
        raise FileNotFoundError(f'Log file {log_file_path} does not exist.')
    kw_set = set(keywords)
    formatted = []
    for raw in path.read_text().splitlines():
        for kw in kw_set:
            if kw in raw:
                after = raw.split(kw, 1)[1].strip()
                parts = after.split(None, 1)
                if len(parts) == 2:
                    ts, msg = parts
                    formatted.append(
                        f"{kw:<20}{' ' * 20}{ts:<20}{' ' * 20}{msg:<20}")
                else:
                    formatted.append(
                        f"{kw:<20}{' ' * 20}{after:<20}{' ' * 20}{'':<20}")
                break
    return formatted

