import numpy as np


def task_func(data_list):
    if not data_list:
        return []
    num_cols = 0
    for item in data_list:
        if isinstance(item, tuple):
            num_cols = max(num_cols, len(item))
        else:
            num_cols = max(num_cols, 1)
    result = []
    for col in range(num_cols):
        col_values = []
        for item in data_list:
            if isinstance(item, tuple):
                try:
                    col_values.append(float(item[col]))
                except (ValueError, TypeError, IndexError):
                    pass
        if not col_values:
            result.append(np.nan)
        else:
            result.append(np.mean(col_values))
    return result

