import math
import logging
logger = logging.getLogger(__name__)


def task_func(points):
    if not isinstance(points, list):
        logger.error('Input must be a list')
        raise TypeError('Input must be a list')
    if len(points) < 2:
        return []
    coords = []
    for idx, p in enumerate(points):
        if isinstance(p, (int, float)):
            x = y = p
        elif isinstance(p, (tuple, list)):
            if len(p) == 1:
                x = y = p[0]
            elif len(p) == 2:
                x, y = p
            else:
                logger.error(
                    f'Point at index {idx} has invalid length {len(p)}')
                raise ValueError(
                    f'Point at index {idx} must have 1 or 2 coordinates')
        else:
            logger.error(
                f'Point at index {idx} is of unsupported type {type(p)}')
            raise TypeError(
                f'Point at index {idx} must be a number or a tuple/list')
        if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
            logger.error(f'Coordinates at index {idx} must be numeric')
            raise TypeError(f'Coordinates at index {idx} must be numeric')
        coords.append((float(x), float(y)))
    distances = []
    for i in range(1, len(coords)):
        dx = coords[i][0] - coords[i - 1][0]
        dy = coords[i][1] - coords[i - 1][1]
        distances.append(math.hypot(dx, dy))
    return distances

