            min(), 'max': arr.max(), 'std': arr.std()}
    stats['current_time'] = datetime.now().strftime(DATE_FORMAT)
    return stats

import numpy as np


def task_func(myList):
    arr = np.array(myList, dtype=float)
    min_val = arr.min()
    max_val = arr.max()
    if max_val == min_val:
        return np.zeros_like(arr)
    return (arr - min_val) / (max_val - min_val)

import random


def task_func(t, n):
    if not isinstance(t, tuple) or not isinstance(n, int):
        raise TypeError(
            'Invalid input types: t must be a tuple and n must be an integer.')
    if len(t) < n:
        raise ValueError('n cannot be larger than the length of the tuple.')
    if n < 0:
        raise ValueError('n must be a non-negative integer.')
    if n == 0:
        return ()
    indices = list(range(len(t)))
    random.shuffle(indices)
    selected_indices = indices[:n]
    result = tuple(t[i] for i in selected_indices)
    return result

