import http.server
import json


class PostRequestHandler(http.server.BaseHTTPRequestHandler):

    def do_POST(self):
        content_length = int(self.headers.get('content-length', 0))
        post_body = self.rfile.read(content_length)
        try:
            data = json.loads(post_body.decode())
        except ValueError:
            self.send_response(400)
            self.end_headers()
            error_response = {'status': 'error', 'message': 'Invalid JSON'}
            self.wfile.write(json.dumps(error_response).encode())
            return
        if 'data' not in data:
            self.send_response(400)
            self.end_headers()
            error_response = {'status': 'error', 'message': 'No data received'}
            self.wfile.write(json.dumps(error_response).encode())
            return
        success_response = {'status': 'success', 'message':
            'Data received successfully.'}
        self.send_response(200)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(success_response).encode())


def task_func():
    return PostRequestHandler

