import json
from typing import List, Tuple, Any


def task_func(json_list: str, r: int) ->List[Tuple[Any]]:
    try:
        data = json.loads(json_list)
        if not isinstance(data, dict) or 'number_list' not in data:
            raise ValueError('Invalid JSON string')
        number_list = data['number_list']
        if not isinstance(number_list, list):
            raise ValueError('Invalid JSON string')
        if r <= 0:
            raise ValueError('Invalid value of r')
        if r > len(number_list):
            return []
        result: List[Tuple[Any]] = []
        n = len(number_list)

        def backtrack(current: List[Any], start: int):
            if len(current) == r:
                result.append(tuple(current))
                return
            for i in range(start, n):
                current.append(number_list[i])
                backtrack(current, i + 1)
                current.pop()
        backtrack([], 0)
        return result
    except json.JSONDecodeError:
        raise ValueError('Invalid JSON string')
    except Exception as e:
        raise e

import random


def task_func(values, weights, n_samples):
    cum_weights = []
    total = 0
    for w in weights:
        total += w
        cum_weights.append(total)
    samples = []
    for _ in range(n_samples):
        r = random.random() * total
        for i, cw in enumerate(cum_weights):
            if r <= cw:
                samples.append(values[i])
                break
    histogram = {}
    for v in samples:
        if v in histogram:
            histogram[v] += 1
        else:
            histogram[v] = 1
    dup_hist = {}
    for v in samples:
        if v in dup_hist:
            dup_hist[v] += 1
        else:
            dup_hist[v] = 1
    return histogram

