from typing import List, Optional


def task_func(log_file_path: str, keywords: List[str]) ->Optional[List[str]]:
    if not keywords:
        return []
    try:
        with open(log_file_path, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        raise
    except UnicodeDecodeError:
        raise
    result = []
    for line in lines:
        matched = False
        for kw in keywords:
            if kw in line:
                parts = line.strip().split(maxsplit=2)
                if len(parts) >= 3:
                    formatted = (
                        f'{kw:>{20}} : {parts[1]:>{20}} : {parts[2]:>{20}}')
                    result.append(formatted)
                else:
                    result.append(f'Line format unexpected: {line.strip()}')
                matched = True
                break
        if not matched:
            continue
    return result if result else []

