import folium
from geopy.distance import geodesic


def task_func(dic):
    if not dic:
        raise ValueError('Input dictionary is empty')
    map = folium.Map(location=[dic[list(dic.keys())[0]]['Lat'], dic[list(
        dic.keys())[0]]['Lon']], zoom_start=10)
    distances = {}
    for i in range(len(list(dic.keys()))):
        for j in range(i + 1, len(list(dic.keys()))):
            loc1 = list(dic.keys())[i]
            loc2 = list(dic.keys())[j]
            distance = geodesic((dic[loc1]['Lat'], dic[loc1]['Lon']), (dic[
                loc2]['Lat'], dic[loc2]['Lon'])).kilometers
            distances[loc1, loc2] = distance
    for key in dic:
        folium.Marker([dic[key]['Lat'], dic[key]['Lon']], popup=key).add_to(map
            )
    return map, distances

