import logging
import secrets


def task_func(dict1):
    """Return a dict mapping department codes starting with 'EMP$$' to lists of employee salaries."""
    logger = logging.getLogger(__name__)
    if not isinstance(dict1, dict):
        logger.error('Input is not a dictionary')
        raise TypeError('dict1 must be a dict')
    result = {}
    for dept, count in dict1.items():
        if not isinstance(dept, str):
            logger.warning('Department key is not a string: %s', dept)
            continue
        if not isinstance(count, int) or count < 0:
            logger.warning('Invalid employee count for %s: %s', dept, count)
            continue
        if dept.startswith('EMP$$'):
            salaries = [(secrets.randbelow(100) + 1) for _ in range(count)]
            result[dept] = salaries
    return result

