import secrets


def task_func(T1, RANGE=100):
    if not isinstance(T1, (tuple, list)):
        raise TypeError('T1 must be a tuple or list of tuples/lists')
    if not isinstance(RANGE, int) or RANGE < 0:
        raise ValueError('RANGE must be a non-negative integer')
    int_values = []
    for sub in T1:
        if not isinstance(sub, (tuple, list)):
            raise TypeError('Each element of T1 must be a tuple or list')
        for item in sub:
            try:
                int_values.append(int(item))
            except Exception:
                raise ValueError(f'Cannot convert {item!r} to int')
    total = sum(int_values)
    random_numbers = [secrets.randbelow(RANGE + 1) for _ in range(total)]
    return collections.Counter(random_numbers)

