from typing import Dict, Any


def task_func(data_list: list[tuple], json_file_name: str='mean_values.json'
    ) ->Dict[str, Any]:
    transposed_data = zip(*data_list)
    filtered_transposed = [list(filter(lambda x: isinstance(x, (int, float)
        ), column)) for column in transposed_data]
    mean_values = {}
    for idx, values in enumerate(filtered_transposed[1:], 1):
        if len(values) > 0:
            current_mean = mean(values)
            mean_values[f'Position {idx}'] = current_mean
    with open(json_file_name, 'w') as f:
        json.dump(mean_values, f)
    return mean_values

