import json


def task_func(json_list, r):
    data = json.loads(json_list)
    if not isinstance(data, dict) or 'number_list' not in data:
        raise Exception('Invalid input')
    number_list = data['number_list']
    if not isinstance(number_list, list):
        raise Exception('number_list must be a list')
    n = len(number_list)
    if r > n:
        return []
    result = []

    def backtrack(start, path):
        if len(path) == r:
            result.append(tuple(path))
            return
        for i in range(start, n):
            path.append(number_list[i])
            backtrack(i + 1, path)
            path.pop()
    backtrack(0, [])
    return result

import hashlib
import random
import base64


def task_func(num, from_base, to_base, alphabet):
    if to_base < 2:
        raise ValueError('Invalid to_base {}'.format(to_base))

    def convert_base(n_str, from_b, to_b):
        try:
            n = int(n_str, from_b)
            return str(int(n).to_bytes((n.bit_length() + 7) // 8, byteorder
                ='big').decode('latin-1'))
        except ValueError:
            raise ValueError('Invalid number format for base {}'.format(from_b)
                )
    salt = ''.join(random.choices(alphabet, k=16))
    converted_num = convert_base(num, from_base, to_base)
    sha_hash = hashlib.sha256(converted_num.encode('utf-8') + salt.encode(
        'utf-8')).digest()
    encoded = base64.b64encode(sha_hash).decode('latin-1')
    return encoded, salt

