import os


def task_func(log_file_path: str, keywords: list):
    """Read a log file and return formatted lines containing specified keywords."""

    def _process(lines, keys):
        formatted = []
        for line in lines:
            for kw in keys:
                if kw in line:
                    parts = line.strip().split(None, 2)
                    if len(parts) == 3:
                        formatted.append(f'{kw:<20}{parts[0]:<20}{parts[2]}')
                    break
        return formatted
    with open(log_file_path, 'r') as f:
        raw_lines = f.readlines()
    return _process(raw_lines, keywords)

