import os
import random
from typing import List, Tuple


def task_func(directory: str, n_files: int) ->str:

    def create_file_paths() ->List[str]:
        return [os.path.join(directory, f'file_{i + 1}.txt') for i in range
            (n_files)]

    def generate_content() ->List[str]:
        return [str(random.randint(1, 100)) for _ in range(n_files)]
    file_paths: List[str] = create_file_paths()
    content_list: List[str] = generate_content()
    try:
        os.makedirs(directory, exist_ok=True)
    except OSError as e:
        raise RuntimeError(f"Failed to create directory '{directory}': {e}")
    results: List[Tuple[str, str]] = []
    for path, content in zip(file_paths, content_list):
        try:
            with open(path, 'w') as file:
                file.write(content)
                file.seek(0)
                results.append((path, content))
        except IOError as e:
            raise RuntimeError(f"Failed to write to file '{path}': {e}")
    return directory

import random
import string
POSSIBLE_LETTERS = ['x', 'y', 'z']


def task_func(word):
    if not all(c in string.ascii_letters for c in word):
        raise ValueError('Input must only contain letters.')
    if len(word) < 2:
        return ['' for _ in POSSIBLE_LETTERS]
    pair_dict = {i: (word[i] + word[i + 1]) for i in range(len(word) - 1)}
    pair_list = list(pair_dict.values())
    return [random.choice(pair_list) for _ in POSSIBLE_LETTERS]

import numpy as np
import pickle


def task_func(data, target):
    if data.size == 0:
        return data, target

    def save_data(d, t):
        with open('save.pkl', 'wb') as f:
            pickle.dump((d, t), f)

    def load_data():
        with open('save.pkl', 'rb') as f:
            return pickle.load(f)
    save_data(data, target)
    loaded = load_data()
    if len(loaded) != 2:
        raise ValueError('Loaded data is invalid')
    loaded_data, loaded_target = loaded
    if not isinstance(loaded_data, np.ndarray) or not isinstance(loaded_target,
        np.ndarray):
        raise TypeError('Loaded data must be numpy arrays')
    return loaded_data, loaded_target

