logging.basicConfig(filename='jquery_removal.log', level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s')


def task_func(directory):
    removed_files = []
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")
    try:
        files = os.listdir(directory)
    except OSError as e:
        logging.error(f"Error accessing directory '{directory}': {str(e)}")
        return 0, []
    for file in files:
        if file.startswith('jquery') and file.endswith('.js'):
            try:
                os.remove(os.path.join(directory, file))
                removed_files.append(file)
                logging.info(f'Successfully removed file: {file}')
            except OSError as e:
                logging.error(f"Error removing file '{file}': {str(e)}")
    return len(removed_files), removed_files

import random


def task_func(values, weights, n_samples):
    if len(values) != len(weights):
        raise ValueError('Values and weights must have the same length')
    result = {}
    for _ in range(n_samples):
        index = random.choices(range(len(values)), weights=weights)[0]
        value = values[index]
        result[value] = result.get(value, 0) + 1
    return result

import collections


def task_func(animal_dict):
    if not isinstance(animal_dict, dict):
        raise TypeError('Input must be a dictionary')
    animal_set = {'cat', 'dog', 'elephant', 'fox', 'camel', 'cow'}
    letter_counts = collections.Counter()
    for key in animal_dict:
        if key in animal_set and isinstance(key, str):
            letter_counts.update(key)
    sorted_letter_counts = dict(sorted(letter_counts.items(), key=lambda
        item: item[1], reverse=True))
    return sorted_letter_counts

