import json


def task_func(json_list, r):
    data = json.loads(json_list)
    number_list = data['number_list']

    def combinations(lst, r):
        if r == 0:
            return [()]
        if not lst or len(lst) < r:
            return []
        first = lst[0]
        rest = lst[1:]
        return [((first,) + c) for c in combinations(rest, r - 1)
            ] + combinations(rest, r)
    result = combinations(number_list, r)
    return [tuple(c) for c in result] if r > 0 else []

