import numpy as np
from scipy import stats


def task_func(df):
    """Perform Shapiro-Wilk test on each column of DataFrame and return p-values."""

    def compute_p_values(columns):
        results = {}
        for col in columns:
            data = df[col].values
            stat, p = stats.shapiro(data)
            results[col] = p
        return results
    p_values = compute_p_values(df.columns)
    return p_values

def task_func(animal_dict):
    animals = {'cat', 'dog', 'elephant', 'fox', 'camel', 'cow'}
    counts = {}
    for name in animal_dict:
        if name in animals:
            for ch in name:
                counts[ch] = counts.get(ch, 0) + 1
    return dict(sorted(counts.items(), key=lambda x: -x[1]))

import numpy as np
from collections import defaultdict


def task_func(values, weights, n_samples):
    if not values or not weights:
        return {}
    if len(values) != len(weights):
        raise ValueError('Values and weights must have the same length')
    total_weight = sum(weights)
    probabilities = [(w / total_weight) for w in weights]
    samples = np.random.choice(values, size=n_samples, p=probabilities)
    histogram = defaultdict(int)
    for num in samples:
        histogram[num] += 1
    return dict(histogram)

