import random
import math


def task_func(range_start=1, range_end=100, pairs_count=10, random_seed=None):
    if random_seed is not None:
        random.seed(random_seed)
    pairs = []
    for _ in range(pairs_count):
        x = random.randint(range_start, range_end)
        y = random.randint(range_start, range_end)
        diff = math.sqrt(abs(x - y))
        pairs.append((x, y, diff))
    return (p for p in pairs)

import random, itertools


def task_func(t, n):
    comb_dict = {}
    for idx, comb in enumerate(itertools.combinations(t, n)):
        comb_dict[idx] = comb
    if not comb_dict:
        return ()
    key = random.choice(list(comb_dict.keys()))
    return comb_dict[key]

