import json


def task_func(data_list, json_file_name):
    numeric_parts = [tuple(item[1:]) for item in data_list]
    if not numeric_parts:
        result = {}
    else:
        sums = [0] * len(numeric_parts[0])
        for part in numeric_parts:
            for i, val in enumerate(part):
                sums[i] += val
        result = {}
        for i, total in enumerate(sums):
            result[f'Position {i + 1}'] = total / len(numeric_parts)
    with open(json_file_name, 'w') as f:
        json.dump(result, f)
    return result

