import json
from typing import List, Tuple


def task_func(json_list: str, r: int) ->List[Tuple]:
    try:
        data = json.loads(json_list)
        number_list = data['number_list']

        def combinations(number_list: List[int], r: int) ->List[Tuple]:
            if r == 0:
                return [()]
            result = []
            for i in range(len(number_list)):
                current = number_list[i]
                rest = number_list[i + 1:]
                for c in combinations(rest, r - 1):
                    result.append((current,) + c)
            return result
        return combinations(number_list, r)
    except Exception as e:
        raise e

